def compute_ecmp(nodes, links, source, flow):
    cost_of, _ = shortest_paths(nodes, links, source)

    # Candidate first hops: targets of up links out of the source.
    first_cost = {}
    for link in links:
        if link["up"] and link["from"] == source:
            first_cost[link["to"]] = link["cost"]

    # Lowest-cost, lexicographically smallest paths from each candidate
    # first hop, so the best equal-cost full path via any of them can be
    # rebuilt as [source] + hop_path.
    hop_cost = {}
    hop_path = {}
    for h in first_cost:
        hop_cost[h], hop_path[h] = shortest_paths(nodes, links, h)

    routes = []
    for n in sorted(nodes):
        if n == source:
            routes.append({"destination": n, "nextHops": [source],
                           "selectedNextHop": source, "cost": 0,
                           "path": [source]})
            continue
        total = cost_of[n]
        if total is None:
            routes.append({"destination": n, "nextHops": [],
                           "selectedNextHop": None, "cost": None, "path": []})
            continue
        # A first hop is usable iff some lowest-cost path to n starts with
        # it; hops are deduplicated and sorted by Unicode code point.
        hops = sorted(
            h for h, w in first_cost.items()
            if hop_cost[h][n] is not None and w + hop_cost[h][n] == total
        )
        key = json.dumps([flow, source, n], ensure_ascii=False,
                         separators=(",", ":")).encode("utf-8")
        digest = hashlib.sha256(key).digest()
        selected = hops[int.from_bytes(digest[:8], "big") % len(hops)]
        routes.append({"destination": n, "nextHops": hops,
                       "selectedNextHop": selected, "cost": total,
                       "path": [source] + hop_path[selected][n]})
    return {"source": source, "flow": flow, "routes": routes}


def dispatch_candidates(nodes, links, source, destination):
    # (total_cost, first_hops, rep_paths) for the equal lowest-cost paths
    # from source to destination, grouped by first hop. When the
    # destination is unreachable, total_cost is None and the other two
    # members are empty lists. Candidate first hops are deduplicated,
    # sorted by Unicode code point order, and each represented by the
    # complete path with the smallest node sequence.
    #
    # Distances to the destination are computed once with a Dijkstra on
    # the reversed up-graph (O(V^2) selection, distances only -- no path
    # sequences are copied), then each node gets the smallest successor
    # still lying on a minimum-cost path to the destination; following
    # successors materializes the lexicographically smallest minimum-cost
    # path from any node. This groups all equal-cost paths by first hop in
    # O(V^2) time and O(V^2) space without enumerating the exponentially
    # many equal-cost simple paths.
    rev = {n: [] for n in nodes}
    for link in links:
        if link["up"]:
            rev[link["to"]].append((link["from"], link["cost"]))

    dist = {n: None for n in nodes}
    dist[destination] = 0
    settled = set()
    while True:
        u = None
        ud = None
        for n in nodes:
            c = dist[n]
            if c is not None and n not in settled \
                    and (ud is None or c < ud):
                u, ud = n, c
        if u is None:
            break
        settled.add(u)
        for v, w in rev[u]:
            if v in settled:
                continue
            nc = ud + w
            if dist[v] is None or nc < dist[v]:
                dist[v] = nc

    total = dist[source]
    if total is None:
        return None, [], []

    # Smallest next node (Unicode code point order) on a shortest route to
    # the destination. Every link cost is >= 1, so along a qualifying edge
    # the distance strictly decreases and successor chains cannot cycle.
    succ = {}
    for link in links:
        if not link["up"]:
            continue
        u, v, w = link["from"], link["to"], link["cost"]
        if dist[u] is not None and dist[v] is not None \
                and w + dist[v] == dist[u]:
            cur = succ.get(u)
            if cur is None or v < cur:
                succ[u] = v

    # A first hop is usable iff some lowest-cost path starts with it.
    first_cost = {}
    for link in links:
        if link["up"] and link["from"] == source:
            first_cost[link["to"]] = link["cost"]
    hops = sorted(h for h, w in first_cost.items()
                  if dist[h] is not None and w + dist[h] == total)

    rep_paths = []
    for h in hops:
        path = [source]
        u = h
        while u != destination:
            path.append(u)
            u = succ[u]
        path.append(destination)
        rep_paths.append(path)
    return total, hops, rep_paths


def compute_dispatch(nodes, links, source, destination, mode, packets):
    total, hops, rep_paths = dispatch_candidates(
        nodes, links, source, destination)
    if total is None:
        return {"source": source, "destination": destination, "mode": mode,
                "nextHops": [], "cost": None,
                "packets": [[pid, flow, None, None, []]
                            for pid, flow in packets]}

    hashes = None
    if mode == "flow":
        # Same rule as ecmp: the first eight bytes of the SHA-256 of the
        # compact [flow, source, destination] JSON, modulo the candidate
        # count. Equal flows always land on the same candidate.
        hashes = {}
        modulus = len(hops)
        for _, flow in packets:
            if flow not in hashes:
                key = json.dumps([flow, source, destination],
                                 ensure_ascii=False,
                                 separators=(",", ":")).encode("utf-8")
                digest = hashlib.sha256(key).digest()
                hashes[flow] = int.from_bytes(digest[:8], "big") % modulus

    rows = []
    for seq, (pid, flow) in enumerate(packets):
        if mode == "flow":
            index = hashes[flow]
        else:
            # Packet mode: round-robin over candidates in DATA order,
            # starting at the first candidate and wrapping at the end;
            # the cursor advances solely with packet position.
            index = seq % len(hops)
        rows.append([pid, flow, index, hops[index], rep_paths[index]])
    return {"source": source, "destination": destination, "mode": mode,
            "nextHops": hops, "cost": total, "packets": rows}


def compute_protect(nodes, links, source, destination, delay, events):
    # Primary: lowest-cost path in the initial up-graph. Backup: lowest-cost
    # path after removing the primary's directed edges. Both are computed
    # once here and never recomputed; events only flip link states.
    up_links = [link for link in links if link["up"]]
    cost_of, path_of = shortest_paths(nodes, up_links, source)
    primary_cost = cost_of[destination]
    primary_path = path_of[destination]
    if primary_path is None:
        backup_cost = None
        backup_path = None
    else:
        removed = set(zip(primary_path, primary_path[1:]))
        backup_links = [link for link in up_links
                        if (link["from"], link["to"]) not in removed]
        bcost_of, bpath_of = shortest_paths(nodes, backup_links, source)
        backup_cost = bcost_of[destination]
        backup_path = bpath_of[destination]

    state = {(link["from"], link["to"]): link["up"] for link in links}

    def usable(path):
        return (path is not None
                and all(state[pair] for pair in zip(path, path[1:])))

    def selected():
        # Prefer an available primary, then the backup, else no path.
        if usable(primary_path):
            return primary_path
        if usable(backup_path):
            return backup_path
        return None

    results = []
    current = selected()
    for event in events:
        before = current if current is not None else []
        pair = (event["from"], event["to"])
        if state[pair] == event["up"]:
            # Repeated setting is idempotent.
            reason = 0
            switch_time = None
            after = before
        else:
            state[pair] = event["up"]
            new = selected()
            after = new if new is not None else []
            if after == before:
                reason = 1
                switch_time = None
            else:
                switch_time = event["time"] + delay
                if new is primary_path:
                    reason = 2
                elif new is None:
                    reason = 5
                elif current is primary_path:
                    reason = 3
                else:
                    reason = 4
            current = new
        results.append({"time": event["time"], "from": event["from"],
                        "to": event["to"], "up": event["up"],
                        "switchTime": switch_time, "reason": reason,
                        "before": before, "after": after})

    return {"source": source, "destination": destination,
            "primary": {"cost": primary_cost, "path": primary_path or []},
            "backup": {"cost": backup_cost, "path": backup_path or []},
            "events": results}


